export const FAWAID_ITEMS = [
  { text: "غزوة بدر برهان على أن النصر بالله لا بالعدد، وهذا درس عملي يُستفاد من السيرة النبوية في الحياة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "السيرة", source: "صحيح البخاري — كتاب المغازي", author_name: "الإمام البخاري" },
  { text: "فتح مكة كان فتح الرحمة، ولم يُقتل فيه إلا من أبى التسليم وقاتل، وهذا درس عملي يُستفاد من السيرة النبوية في الحياة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "السيرة", source: "البداية والنهاية — ابن كثير", author_name: "ابن كثير" },
  { text: "ما نقص مال من صدقة، وما زاد الله عبداً بعفو إلا عزاً، وما تواضع أحد لله إلا رفعه الله، وهذا من آداب طلب العلم وأصوله التي يُرجى بها نفع العلم. كما ثبت في السنة الصحيحة.", category: "طلب العلم", source: "رواه مسلم", author_name: "صحيح مسلم" },
  { text: "خير ما يخلّف الرجل من بعده ثلاث: ولد صالح يدعو له، وصدقة تجري يبلغه أجرها، وعلم يُعمل به من بعده. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "طلب العلم", source: "رواه ابن ماجه (242) — حسنه الألباني", author_name: "سنن ابن ماجه" },
  { text: "العلم يُورث الخشية، والخشية تُورث العمل، والعمل يُورث الجنة، وهذا من آداب طلب العلم وأصوله التي يُرجى بها نفع العلم. كما دلّ عليه الكتاب والسنة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "طلب العلم", source: "إِنَّمَا يَخْشَى اللَّهَ مِنْ عِبَادِهِ الْعُلَمَاءُ — فاطر: 28", author_name: "الإمام ابن القيم" },
  { text: "الداعي إلى الله يبدأ بنفسه قبل غيره — فكيف ينهى الناس ويأتي ما ينهى عنه؟، وهذا من آداب الدعوة إلى الله بالحكمة والموعظة الحسنة. كما دلّ عليه الكتاب والسنة.", category: "الدعوة", source: "أَتَأْمُرُونَ النَّاسَ بِالْبِرِّ وَتَنسَوْنَ أَنفُسَكُمْ — البقرة: 44", author_name: "القرآن الكريم" },
  { text: "الرفق ما وُضع في شيء إلا زانه، وما نُزع من شيء إلا شانه، وهذا من آداب الدعوة إلى الله بالحكمة والموعظة الحسنة. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الدعوة", source: "رواه مسلم", author_name: "صحيح مسلم" },
  { text: "اتقِ الله في أهلك وولدك كما تتقيه في مالك، وهذا من أصول التربية الإسلامية التي يُنشأ عليها الولد. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "التربية", source: "أثر السلف — مدارج السالكين", author_name: "ابن قيم الجوزية" },
  { text: "الولد يتشكّل على يد والديه؛ فكن القدوة قبل أن تكون الموجّه، وهذا من أصول التربية الإسلامية التي يُنشأ عليها الولد. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "التربية", source: "كل مولود يولد على الفطرة — متفق عليه", author_name: "صحيح البخاري" },
  { text: "الاستئذان ثلاث، فإن أُذن وإلا فارجع، وهذا من آداب الإسلام التي تُجمّل المسلم وتُقربه من ربه. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الآداب", source: "رواه مسلم", author_name: "صحيح مسلم" },
  { text: "إياكم والظن فإن الظن أكذب الحديث، وهذا من آداب الإسلام التي تُجمّل المسلم وتُقربه من ربه. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الآداب", source: "متفق عليه", author_name: "صحيح البخاري" },
  { text: "حسن الخلق بابٌ من أبواب الجنة؛ قال ﷺ: «أكثر ما يُدخل الجنة تقوى الله وحسن الخلق» — الترمذي ٢٠٠٤، صححه الألباني. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الآداب", source: "الترمذي ٢٠٠٤ — صحيح", author_name: "سنن الترمذي" },
  { text: "الكبر بطر الحق وغمط الناس، وهذا من مكارم الأخلاق التي أمر بها الشرع. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الأخلاق", source: "رواه مسلم", author_name: "صحيح مسلم" },
  { text: "من حُرم الرفق حُرم الخير كله، وهذا من مكارم الأخلاق التي أمر بها الشرع. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الأخلاق", source: "رواه مسلم", author_name: "صحيح مسلم" },
  { text: "الغيبة ذكرك أخاك بما يكره — فيها إثم عظيم وإن كان المقول فيه كذلك، وهذا من مكارم الأخلاق التي أمر بها الشرع. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الأخلاق", source: "رواه مسلم", author_name: "صحيح مسلم" },
  { text: "تلاوة آية بتدبّر وفهم خير من ختمة بلا تفكّر، فالتعامل مع كتاب الله يستوجب تدبره وحفظه والعمل بما فيه. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "القرآن", source: "أثر سلفي — ابن القيم: مفتاح دار السعادة", author_name: "ابن قيم الجوزية" },
  { text: "من قرأ حرفاً من كتاب الله فله به حسنة والحسنة بعشر أمثالها، فالتعامل مع كتاب الله يستوجب تدبره وحفظه والعمل بما فيه. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "القرآن", source: "الترمذي ٢٩١٠ — صححه الألباني", author_name: "سنن الترمذي" },
  { text: "أهل القرآن هم أهل الله وخاصته، فالتعامل مع كتاب الله يستوجب تدبره وحفظه والعمل بما فيه. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "القرآن", source: "رواه النسائي وابن ماجه — صحيح الألباني", author_name: "سنن ابن ماجه" },
  { text: "التفكر في النفس والخلق يدل على عظمة الخالق؛ قال تعالى: ﴿وَفِي أَنفُسِكُمْ أَفَلَا تُبْصِرُونَ﴾. وأما لفظ «من عرف نفسه عرف ربه» فليس بحديث مرفوع. والدعوة إليه.", category: "العقيدة", source: "الذاريات: ٢١؛ أنكره النووي وابن تيمية كحديث مرفوع", author_name: "صحيح البخاري" },
  { text: "الحياء شعبة من شعب الإيمان؛ ومن قلّ حياؤه ضعف إيمانه، وهذا من أصول الاعتقاد التي يُبنى عليها إيمان المسلم وعمله. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "العقيدة", source: "الشطر الأول حديث متفق عليه: «الإيمان بضع وستون شعبة، والحياء شعبة من الإيمان»؛ الشطر الثاني تعليق تفسيري وليس من نص الحديث", author_name: "صحيح البخاري" },
  { text: "الدجال يخرج من المشرق؛ وعلامة قربه ظهور الفتن وكثرة الكذب، وهذا من أصول الاعتقاد التي يُبنى عليها إيمان المسلم وعمله. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "العقيدة", source: "رواه البخاري ومسلم — أشراط الساعة", author_name: "صحيح البخاري" },
  { text: "اتقوا الله وصلوا أرحامكم، وهذا من هدي النبي ﷺ الذي يجب على المسلم معرفته والعمل به. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الحديث", source: "رواه البيهقي في شعب الإيمان عن ابن مسعود — حسّنه الألباني في صحيح الجامع", author_name: "صحيح الجامع للألباني" },
  { text: "إن الله يحب إذا عمل أحدكم عملاً أن يتقنه، وهذا من هدي النبي ﷺ الذي يجب على المسلم معرفته والعمل به. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الحديث", source: "رواه البيهقي — صحيح الألباني", author_name: "السلسلة الصحيحة" },
  { text: "من صمت نجا — السكوت أمان، والكلام مسؤولية، وهذا من هدي النبي ﷺ الذي يجب على المسلم معرفته والعمل به. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الحديث", source: "الترمذي ٢٥٠١ — حسّنه الألباني", author_name: "سنن الترمذي" },
  { text: "الفتح الأكبر كان بلا حرب؛ دخل النبي ﷺ مكة وعفا عن أهلها — قدوة في العفو والرحمة، وهذا درس عملي يُستفاد من السيرة النبوية في الحياة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "السيرة", source: "صحيح البخاري — كتاب المغازي", author_name: "الإمام البخاري" }
];
